"""Asset-grounded director prompts after explicit user approval."""
import json
from project_ops import ROOT,helper,commit
p=helper.read(ROOT/'project.json')
if helper.review_state(ROOT,p)['status']!='approved':raise RuntimeError('Asset approval required')
p['aspect_ratio']='21:9'
p['resolution']='720p'
p['master_prompt_raw']=p['master_prompt_raw'].replace('Final director prompts wait for approval of the revised image set.','Approved original-cast director prompts and native audio.').replace('16:9','21:9').replace('Final scene prompts pending visual approval.','Native 720p ultrawide output. All images approved; text prompts direct the motion and cuts.')
p['detailed_script']=p['detailed_script'].replace('MUGMAN','PIP').replace('CUPHEAD','RIFF').replace('Recast screenplay awaiting revised asset approval','Approved original-cast production screenplay').replace('16:9','21:9').replace('Rough timed screenplay — exact 150 seconds; final shot prompts await asset approval.','Approved production screenplay — exact 150 seconds, 21:9, native 720p.')
for c in p['chapters']:
    for line in c['dialogue']:line['text']=line['text'].replace('MUGMAN','PIP').replace('CUPHEAD','RIFF')
p['render_tool_discovery']['direct_api_authorization']='proceed. use the seedance 2.5 credentials in .env. 21:9, 720p'
p['render_configuration']={'provider':'BytePlus ModelArk','requested_model':'Seedance 2.5','aspect_ratio':'21:9','resolution':'720p','expected_native_dimensions':[1470,630],'generate_audio':True,'exact_duration_seconds':150,'credential_source':'Workspace .env; only VOLC_ACCESS_KEY, VOLC_SECRET_KEY_RAW, VOLC_PROJECT_NAME, VOLC_ENDPOINT_SEEDANCE_25 read; values stay in memory','references':'Selected approved image assets only; no storyboard or contact sheet','documentation':['https://docs.byteplus.com/zh-TW/docs/modelark/seedance-2-5','https://docs.byteplus.com/ja/docs/modelark/create-video-generation-task-api']}

